      },
      {
        "system": "MongoDB",
        "guarantees": ["Consistency", "Availability"],
        "sacrifice": "Partition Tolerance",
        "description": "MongoDB can be configured to prioritize Consistency and Availability in a single data center. However, it might not handle network partitions well, as it could stop processing requests to maintain consistency."
