"using System;
using System.Text.RegularExpressions;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace EmailValidator.Tests
{
    [TestClass]
    public class EmailValidatorTests
    {
        [TestMethod]
        public void ValidateEmail_ValidEmail_ReturnsTrue()
        {
            // Arrange
            string validEmail = "test.user@example.com";

            // Act
            bool result = EmailValidator.ValidateEmail(validEmail);

            // Assert
            Assert.IsTrue(result);
        }

        [TestMethod]
        public void ValidateEmail_InvalidEmailNoAtSymbol_ReturnsFalse()
        {
            // Arrange
            string invalidEmail = "test.userexample.com";

            // Act
            bool result = EmailValidator.ValidateEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void ValidateEmail_InvalidEmailMultipleAtSymbols_ReturnsFalse()
        {
            // Arrange
            string invalidEmail = "test@@user@example.com";

            // Act
            bool result = EmailValidator.ValidateEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void ValidateEmail_InvalidEmailNoDomain_ReturnsFalse()
        {
            // Arrange
            string invalidEmail = "test.user@";

            // Act
            bool result = EmailValidator.ValidateEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void ValidateEmail_NullEmail_ReturnsFalse()
        {
            // Arrange
            string invalidEmail = null;

            // Act
            bool result = EmailValidator.ValidateEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void ValidateEmail_EmptyEmail_ReturnsFalse()
        {
            // Arrange
            string invalidEmail = "";

            // Act
            bool result = EmailValidator.ValidateEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }
    }

    public class EmailValidator
    {
        private static readonly Regex EmailRegex = new Regex(
            @"^[^@\s]+@[^@\s]+\.[^@\s]+$",
            RegexOptions.Compiled);

        public static bool ValidateEmail(string email)
        {
            if (string.IsNullOrEmpty(email))
                return false;

            return EmailRegex.IsMatch(email);
        }
    }
}"

"function mergeTwoLists(l1, l2) {
    const dummy = new ListNode();
    let current = dummy;

    while (l1 && l2) {
        if (l1.val < l2.val) {
            current.next = l1;
            l1 = l1.next;
        } else {
            current.next = l2;
            l2 = l2.next;
        }
        current = current.next;
    }

    // Attach the remaining elements
    current.next = l1 || l2;

    return dummy.next;
}

// Definition for a singly-linked list node
class ListNode {
    constructor(val = 0, next = null) {
        this.val = val;
        this.next = next;
    }
}"

